def backfill_session_class_snapshots(apps, schema_editor):
    """Bind historical sessions to their recorded label without guessing source classes."""
    Session = apps.get_model("assessment", "ExperimentSession")
    ClassSnapshot = apps.get_model("experiments", "ExperimentClassSnapshot")
    ParticipantSnapshot = apps.get_model(
        "experiments", "ExperimentVersionParticipantSnapshot"
    )

    snapshot_cache = {}
    for session in Session.objects.filter(class_snapshot__isnull=True).iterator():
        label = session.class_snapshot_name or ""
        participant = ParticipantSnapshot.objects.filter(
            version_id=session.version_id,
            student_id=session.student_id,
        ).first()
        if participant is not None:
            class_snapshot = participant.class_snapshot
            display_name = ""
            if class_snapshot is not None:
                display_name = (
                    f"{class_snapshot.academic_year_snapshot} "
                    f"{class_snapshot.name_snapshot}"
                ).strip()
            if class_snapshot is not None and display_name == label:
                Session.objects.filter(pk=session.pk).update(
                    class_snapshot_id=class_snapshot.pk
                )
                continue
        cache_key = (session.version_id, label)
        if cache_key not in snapshot_cache:
            snapshot_cache[cache_key] = ClassSnapshot.objects.create(
                version_id=session.version_id,
                name_snapshot=label,
                academic_year_snapshot="",
                capture_mode=("legacy_label_projection" if label else "unrecorded"),
            )
        class_snapshot = snapshot_cache[cache_key]
        Session.objects.filter(pk=session.pk).update(class_snapshot_id=class_snapshot.pk)
        if participant is None:
            ParticipantSnapshot.objects.create(
                version_id=session.version_id,
                student_id=session.student_id,
                class_snapshot_id=class_snapshot.pk,
            )


def backfill_grade_validity(apps, schema_editor):
    GradeRecord = apps.get_model("assessment", "GradeRecord")
    submission_ids = (
        GradeRecord.objects.order_by()
        .values_list("submission_id", flat=True)
        .distinct()
    )
    for submission_id in submission_ids.iterator():
        grades = list(
            GradeRecord.objects.filter(submission_id=submission_id).order_by("-version")
        )
        effective_found = False
        for grade in grades:
            if grade.status == "completed" and not effective_found:
                validity = "effective"
                effective_found = True
            elif grade.status == "completed":
                validity = "superseded"
            else:
                validity = "candidate"
            GradeRecord.objects.filter(pk=grade.pk).update(validity_status=validity)


